1	import { categoriasPadrao } from '../data/categoriasPadrao';
2	import { falha, ok, type AppState, type Resultado } from '../domain/types';
3	
4	/** Toda chave escrita pelo app começa com este prefixo. */
5	export const PREFIXO = 'financas:';
6	export const CHAVE_ESTADO = `${PREFIXO}estado`;
7	export const SCHEMA_ATUAL = 2;
8	
9	export function estadoInicial(): AppState {
10	  return {
11	    schemaVersion: SCHEMA_ATUAL,
12	    contas: [],
13	    categorias: categoriasPadrao(),
14	    transacoes: [],
15	    orcamentos: [],
16	    metas: [],
17	    recorrencias: [],
18	    mapeamentosCsv: {},
19	    importacoes: [],
20	    pagamentosFatura: [],
21	    agenda: [],
22	    regras: [],
23	    investimentos: [],
24	    dividas: [],
25	  };
26	}
27	
28	export type Carga =
29	  | { tipo: 'ok'; estado: AppState }
30	  | { tipo: 'corrompido'; bruto: string }
31	  | { tipo: 'versao-futura'; bruto: string; versao: number };
32	
33	type Dados = Record<string, unknown>;
34	
35	/** Migrações indexadas pela versão de origem: `migracoes[n]` leva de n para n+1. */
36	const migracoes: Record<number, (dados: Dados) => Dados> = {
37	  0: (dados) => ({
38	    ...dados,
39	    schemaVersion: 1,
40	    contas: dados.contas ?? [],
41	    categorias: dados.categorias ?? categoriasPadrao(),
42	    transacoes: dados.transacoes ?? [],
43	    orcamentos: dados.orcamentos ?? [],
44	    metas: dados.metas ?? [],
45	    recorrencias: dados.recorrencias ?? [],
46	    mapeamentosCsv: dados.mapeamentosCsv ?? {},
47	    importacoes: dados.importacoes ?? [],
48	  }),
49	  // v2: pagamentos de fatura de cartão.
50	  1: (dados) => ({ ...dados, schemaVersion: 2, pagamentosFatura: dados.pagamentosFatura ?? [] }),
51	};
52	
53	const CHAVES_LISTA = ['contas', 'categorias', 'transacoes', 'orcamentos', 'metas', 'recorrencias', 'importacoes', 'pagamentosFatura'] as const;
54	
55	function ehObjeto(x: unknown): x is Dados {
56	  return typeof x === 'object' && x !== null && !Array.isArray(x);
57	}
58	
59	function estruturaValida(dados: Dados): boolean {
60	  return (
61	    CHAVES_LISTA.every((k) => Array.isArray(dados[k])) &&
62	    ehObjeto(dados.mapeamentosCsv) &&
63	    dados.schemaVersion === SCHEMA_ATUAL
64	  );
65	}
66	
67	/** Migra um objeto qualquer até a versão atual. Versões futuras são recusadas. */
68	export function migrar(bruto: unknown): { tipo: 'ok'; estado: AppState } | { tipo: 'corrompido' } | { tipo: 'versao-futura'; versao: number } {
69	  if (!ehObjeto(bruto)) return { tipo: 'corrompido' };
70	  let dados: Dados = bruto;
71	  const versaoLida = dados.schemaVersion === undefined ? 0 : dados.schemaVersion;
72	  if (typeof versaoLida !== 'number' || !Number.isInteger(versaoLida) || versaoLida < 0) {
73	    return { tipo: 'corrompido' };
74	  }
75	  if (versaoLida > SCHEMA_ATUAL) return { tipo: 'versao-futura', versao: versaoLida };
76	  if (versaoLida === 0 && !CHAVES_LISTA.some((k) => k in dados)) return { tipo: 'corrompido' };
77	  for (let v = versaoLida; v < SCHEMA_ATUAL; v++) {
78	    const migracao = migracoes[v];
79	    if (!migracao) return { tipo: 'corrompido' };
80	    dados = migracao(dados);
81	  }
82	  // Chaves aditivas (novos módulos) ausentes em dados antigos recebem o valor inicial, sem migração.
83	  const padrao = estadoInicial() as unknown as Dados;
84	  for (const chave of Object.keys(padrao)) if (dados[chave] === undefined) dados = { ...dados, [chave]: padrao[chave] };
85	  if (!estruturaValida(dados)) return { tipo: 'corrompido' };
86	  return { tipo: 'ok', estado: dados as unknown as AppState };
87	}
88	
89	export function carregar(storage: Storage): Carga {
90	  let bruto: string | null;
91	  try {
92	    bruto = storage.getItem(CHAVE_ESTADO);
93	  } catch {
94	    return { tipo: 'ok', estado: estadoInicial() };
95	  }
96	  if (bruto === null) return { tipo: 'ok', estado: estadoInicial() };
97	  let parsed: unknown;
98	  try {
99	    parsed = JSON.parse(bruto);
100	  } catch {
101	    return { tipo: 'corrompido', bruto };
102	  }
103	  const r = migrar(parsed);
104	  if (r.tipo === 'ok') return r;
105	  if (r.tipo === 'versao-futura') return { tipo: 'versao-futura', bruto, versao: r.versao };
106	  return { tipo: 'corrompido', bruto };
107	}
108	
109	/** Lança se o navegador recusar a gravação (cota excedida, armazenamento bloqueado). */
110	export function salvar(estado: AppState, storage: Storage): void {
111	  storage.setItem(CHAVE_ESTADO, JSON.stringify(estado));
112	}
113	
114	export function apagarTudo(storage: Storage): void {
115	  const chaves: string[] = [];
116	  for (let i = 0; i < storage.length; i++) {
117	    const chave = storage.key(i);
118	    if (chave?.startsWith(PREFIXO)) chaves.push(chave);
119	  }
120	  chaves.forEach((c) => storage.removeItem(c));
121	}
122	
123	export function exportarJson(estado: AppState): string {
124	  return JSON.stringify(estado, null, 2);
125	}
126	
127	/** Lê um arquivo de exportação, migrando se necessário. */
128	export function importarJson(texto: string): Resultado<AppState> {
129	  let parsed: unknown;
130	  try {
131	    parsed = JSON.parse(texto);
132	  } catch {
133	    return falha('O arquivo não é um JSON válido.');
134	  }
135	  const r = migrar(parsed);
136	  if (r.tipo === 'ok') return ok(r.estado);
137	  if (r.tipo === 'versao-futura') {
138	    return falha(`O arquivo foi gerado por uma versão mais nova do app (esquema ${r.versao}).`);
139	  }
140	  return falha('O arquivo não parece ser uma exportação deste app.');
141	}
