1	import { saldoConta } from './contas';
2	import { dataValida, diasNoMes, mesDe, somarMeses } from './date';
3	import { novoId, proximoTempo } from './id';
4	import { DESCRICAO_MAX } from './transacoes';
5	import {
6	  falha,
7	  ok,
8	  type AppState,
9	  type CartaoConfig,
10	  type Centavos,
11	  type Conta,
12	  type DataISO,
13	  type Mes,
14	  type PagamentoFatura,
15	  type Resultado,
16	  type Transacao,
17	} from './types';
18	
19	export const PARCELAS_MIN = 2;
20	export const PARCELAS_MAX = 48;
21	
22	const dia2 = (n: number) => String(n).padStart(2, '0');
23	
24	export function cartoesAtivos(contas: Conta[]): Conta[] {
25	  return contas.filter((c) => c.tipo === 'cartao' && !c.arquivada);
26	}
27	
28	/** Último dia do ciclo da fatura de `mes` (o dia de fechamento, inclusive). */
29	export function fechamentoFatura(config: CartaoConfig, mes: Mes): DataISO {
30	  return `${mes}-${dia2(config.diaFechamento)}`;
31	}
32	
33	/** Ciclo da fatura de `mes`: do dia seguinte ao fechamento anterior até o fechamento de `mes`. */
34	export function cicloFatura(config: CartaoConfig, mes: Mes): { inicio: DataISO; fim: DataISO } {
35	  const anterior = fechamentoFatura(config, somarMeses(mes, -1));
36	  const [a, m, d] = anterior.split('-').map(Number);
37	  const proximo = new Date(Date.UTC(a, m - 1, d + 1)).toISOString().slice(0, 10);
38	  return { inicio: proximo, fim: fechamentoFatura(config, mes) };
39	}
40	
41	/** Vence no mês do fechamento se o vencimento é depois do fechamento; senão, no mês seguinte. */
42	export function vencimentoFatura(config: CartaoConfig, mes: Mes): DataISO {
43	  const mesVenc = config.diaVencimento > config.diaFechamento ? mes : somarMeses(mes, 1);
44	  return `${mesVenc}-${dia2(config.diaVencimento)}`;
45	}
46	
47	/** Fatura aberta hoje: a que fecha no mês corrente, ou no seguinte se o fechamento já passou. */
48	export function mesFaturaAberta(config: CartaoConfig, hoje: DataISO): Mes {
49	  const dia = Number(hoje.slice(8, 10));
50	  return dia <= config.diaFechamento ? mesDe(hoje) : somarMeses(mesDe(hoje), 1);
51	}
52	
53	export function transacoesDaFatura(estado: AppState, conta: Conta, mes: Mes): Transacao[] {
54	  if (!conta.cartao) return [];
55	  const { inicio, fim } = cicloFatura(conta.cartao, mes);
56	  return estado.transacoes
57	    .filter((t) => t.contaId === conta.id && t.data >= inicio && t.data <= fim)
58	    .sort((a, b) => (a.data < b.data ? 1 : a.data > b.data ? -1 : b.criadaEm - a.criadaEm));
59	}
60	
61	/** Compras menos estornos (receitas) no ciclo. */
62	export function totalFatura(transacoes: Transacao[]): Centavos {
63	  return transacoes.reduce((s, t) => s + (t.tipo === 'despesa' ? t.valor : -t.valor), 0);
64	}
65	
66	export function pagamentosDaFatura(estado: AppState, contaId: string, mes: Mes): PagamentoFatura[] {
67	  return estado.pagamentosFatura.filter((p) => p.contaCartaoId === contaId && p.mesFatura === mes);
68	}
69	
70	export type SituacaoFatura = 'aberta' | 'fechada' | 'paga';
71	
72	export interface ResumoFatura {
73	  transacoes: Transacao[];
74	  total: Centavos;
75	  pago: Centavos;
76	  restante: Centavos;
77	  vencimento: DataISO;
78	  situacao: SituacaoFatura;
79	}
80	
81	export function resumoFatura(estado: AppState, conta: Conta, mes: Mes, hoje: DataISO): ResumoFatura | null {
82	  if (!conta.cartao) return null;
83	  const transacoes = transacoesDaFatura(estado, conta, mes);
84	  const total = totalFatura(transacoes);
85	  const pago = pagamentosDaFatura(estado, conta.id, mes).reduce((s, p) => s + p.valor, 0);
86	  const restante = Math.max(total - pago, 0);
87	  const { fim } = cicloFatura(conta.cartao, mes);
88	  const situacao: SituacaoFatura = hoje <= fim ? 'aberta' : restante > 0 ? 'fechada' : 'paga';
89	  return { transacoes, total, pago, restante, vencimento: vencimentoFatura(conta.cartao, mes), situacao };
90	}
91	
92	export interface LimiteCartao {
93	  usado: Centavos;
94	  disponivel: Centavos;
95	  excedido: boolean;
96	}
97	
98	/** Usado = dívida atual (saldo negativo do cartão); nunca negativo. */
99	export function limiteCartao(estado: AppState, conta: Conta): LimiteCartao | null {
100	  if (!conta.cartao) return null;
101	  const usado = Math.max(-saldoConta(estado, conta.id), 0);
102	  const disponivel = conta.cartao.limite - usado;
103	  return { usado, disponivel, excedido: disponivel < 0 };
104	}
105	
106	// ------------------------------------------------------------- parcelamento
107	
108	export interface DadosCompraParcelada {
109	  contaId: string;
110	  descricao: string;
111	  valorTotal: Centavos;
112	  parcelas: number;
113	  /** Data da primeira parcela. */
114	  data: DataISO;
115	  categoriaId: string;
116	}
117	
118	/** Divide em centavos exatos: o resto da divisão fica na primeira parcela. */
119	export function dividirParcelas(total: Centavos, parcelas: number): Centavos[] {
120	  const base = Math.floor(total / parcelas);
121	  const resto = total - base * parcelas;
122	  return Array.from({ length: parcelas }, (_, i) => (i === 0 ? base + resto : base));
123	}
124	
125	/** Mesmo dia nos meses seguintes, limitado ao último dia de cada mês. */
126	export function dataDaParcela(primeira: DataISO, indice: number): DataISO {
127	  const mes = somarMeses(mesDe(primeira), indice);
128	  const [ano, m] = mes.split('-').map(Number);
129	  const dia = Math.min(Number(primeira.slice(8, 10)), diasNoMes(ano, m));
130	  return `${mes}-${dia2(dia)}`;
131	}
132	
133	export function criarCompraParcelada(estado: AppState, dados: DadosCompraParcelada): Resultado<AppState> {
134	  const conta = estado.contas.find((c) => c.id === dados.contaId);
135	  if (!conta || conta.tipo !== 'cartao' || conta.arquivada) return falha('Escolha um cartão ativo.', 'contaId');
136	  const descricao = dados.descricao.trim();
137	  if (!descricao) return falha('Informe a descrição da compra.', 'descricao');
138	  if (!Number.isInteger(dados.parcelas) || dados.parcelas < PARCELAS_MIN || dados.parcelas > PARCELAS_MAX) {
139	    return falha(`O número de parcelas deve ficar entre ${PARCELAS_MIN} e ${PARCELAS_MAX}.`, 'parcelas');
140	  }
141	  if (!Number.isInteger(dados.valorTotal) || dados.valorTotal < dados.parcelas) {
142	    return falha('O valor total deve ser de ao menos 1 centavo por parcela.', 'valorTotal');
143	  }
144	  if (!dataValida(dados.data)) return falha('Informe uma data válida.', 'data');
145	  const categoria = estado.categorias.find((c) => c.id === dados.categoriaId);
146	  if (!categoria || categoria.tipo !== 'despesa' || categoria.arquivada) return falha('Escolha uma categoria de despesa ativa.', 'categoriaId');
147	
148	  const grupoId = novoId();
149	  const valores = dividirParcelas(dados.valorTotal, dados.parcelas);
150	  const novas: Transacao[] = valores.map((valor, i) => {
151	    const sufixo = ` (${i + 1}/${dados.parcelas})`;
152	    return {
153	      id: novoId(),
154	      contaId: conta.id,
155	      categoriaId: categoria.id,
156	      tipo: 'despesa',
157	      valor,
158	      data: dataDaParcela(dados.data, i),
159	      descricao: descricao.slice(0, DESCRICAO_MAX - sufixo.length) + sufixo,
160	      criadaEm: proximoTempo(),
161	      parcela: { grupoId, numero: i + 1, total: dados.parcelas },
162	    };
163	  });
164	  return ok({ ...estado, transacoes: [...estado.transacoes, ...novas] });
165	}
166	
167	export type EscopoExclusao = 'uma' | 'todas';
168	
169	/** Exclui só a parcela ou todas as parcelas do mesmo grupo. */
170	export function excluirParcela(estado: AppState, transacaoId: string, escopo: EscopoExclusao): Resultado<AppState> {
171	  const alvo = estado.transacoes.find((t) => t.id === transacaoId);
172	  if (!alvo) return falha('Transação não encontrada.');
173	  const grupo = alvo.parcela?.grupoId;
174	  const remover = (t: Transacao) => (escopo === 'todas' && grupo ? t.parcela?.grupoId === grupo : t.id === transacaoId);
175	  return ok({ ...estado, transacoes: estado.transacoes.filter((t) => !remover(t)) });
176	}
177	
178	// ---------------------------------------------------------------- pagamentos
179	
180	export interface DadosPagamento {
181	  contaCartaoId: string;
182	  mesFatura: Mes;
183	  valor: Centavos;
184	  data: DataISO;
185	  contaOrigemId: string;
186	}
187	
188	export function registrarPagamento(estado: AppState, dados: DadosPagamento, hoje: DataISO): Resultado<AppState> {
189	  const cartao = estado.contas.find((c) => c.id === dados.contaCartaoId);
190	  if (!cartao || cartao.tipo !== 'cartao' || !cartao.cartao) return falha('Cartão não configurado.');
191	  const origem = estado.contas.find((c) => c.id === dados.contaOrigemId);
192	  if (!origem || origem.arquivada || origem.tipo === 'cartao') return falha('Escolha uma conta de origem ativa que não seja cartão.', 'contaOrigemId');
193	  if (!Number.isInteger(dados.valor) || dados.valor <= 0) return falha('O valor deve ser maior que zero.', 'valor');
194	  if (!dataValida(dados.data)) return falha('Informe uma data válida.', 'data');
195	  const resumo = resumoFatura(estado, cartao, dados.mesFatura, hoje);
196	  if (!resumo) return falha('Cartão não configurado.');
197	  if (dados.valor > resumo.restante) return falha('O valor é maior que o restante da fatura.', 'valor');
198	  const pagamento: PagamentoFatura = { id: novoId(), ...dados };
199	  return ok({ ...estado, pagamentosFatura: [...estado.pagamentosFatura, pagamento] });
200	}
201	
202	export function excluirPagamento(estado: AppState, id: string): Resultado<AppState> {
203	  if (!estado.pagamentosFatura.some((p) => p.id === id)) return falha('Pagamento não encontrado.');
204	  return ok({ ...estado, pagamentosFatura: estado.pagamentosFatura.filter((p) => p.id !== id) });
205	}
