1	import { novoId, proximoTempo } from './id';
2	import { falha, ok, type AppState, type CartaoConfig, type Centavos, type Conta, type Resultado, type TipoConta, type Transacao } from './types';
3	
4	export const TIPOS_CONTA: TipoConta[] = ['corrente', 'poupanca', 'dinheiro', 'investimento', 'cartao'];
5	
6	export const ROTULO_TIPO_CONTA: Record<TipoConta, string> = {
7	  corrente: 'Conta corrente',
8	  poupanca: 'Poupança',
9	  dinheiro: 'Dinheiro',
10	  investimento: 'Investimento',
11	  cartao: 'Cartão de crédito',
12	};
13	
14	export const NOME_MAX = 40;
15	
16	export interface DadosConta {
17	  nome: string;
18	  tipo: TipoConta;
19	  saldoInicial: Centavos;
20	  /** Ciclo e limite; só vale para o tipo cartão e é opcional até o usuário configurar. */
21	  cartao?: CartaoConfig;
22	}
23	
24	const normalizar = (nome: string) => nome.trim().toLocaleLowerCase('pt-BR');
25	
26	export function validarNomeConta(contas: Conta[], nome: string, ignorarId?: string): Resultado<string> {
27	  const limpo = nome.trim();
28	  if (!limpo) return falha('Informe o nome da conta.', 'nome');
29	  if (limpo.length > NOME_MAX) return falha(`O nome deve ter no máximo ${NOME_MAX} caracteres.`, 'nome');
30	  const duplicada = contas.some((c) => !c.arquivada && c.id !== ignorarId && normalizar(c.nome) === normalizar(limpo));
31	  if (duplicada) return falha('Já existe uma conta ativa com esse nome.', 'nome');
32	  return ok(limpo);
33	}
34	
35	/** Dias de 1 a 28 e limite maior que zero. O campo do erro indica qual valor corrigir. */
36	export function validarCartao(c: CartaoConfig): Resultado<CartaoConfig> {
37	  const diaOk = (d: number) => Number.isInteger(d) && d >= 1 && d <= 28;
38	  if (!diaOk(c.diaFechamento)) return falha('O dia de fechamento deve ser um inteiro de 1 a 28.', 'diaFechamento');
39	  if (!diaOk(c.diaVencimento)) return falha('O dia de vencimento deve ser um inteiro de 1 a 28.', 'diaVencimento');
40	  if (!Number.isInteger(c.limite) || c.limite <= 0) return falha('O limite deve ser maior que zero.', 'limite');
41	  return ok(c);
42	}
43	
44	/** Só contas do tipo cartão guardam configuração de ciclo. */
45	function cartaoDaConta(dados: DadosConta): Resultado<CartaoConfig | undefined> {
46	  if (dados.tipo !== 'cartao' || !dados.cartao) return ok(undefined);
47	  return validarCartao(dados.cartao);
48	}
49	
50	export function criarConta(estado: AppState, dados: DadosConta): Resultado<AppState> {
51	  const nome = validarNomeConta(estado.contas, dados.nome);
52	  if (!nome.ok) return nome;
53	  const cartao = cartaoDaConta(dados);
54	  if (!cartao.ok) return cartao;
55	  const conta: Conta = {
56	    id: novoId(),
57	    nome: nome.valor,
58	    tipo: dados.tipo,
59	    saldoInicial: dados.saldoInicial,
60	    arquivada: false,
61	    criadaEm: proximoTempo(),
62	    ...(cartao.valor ? { cartao: cartao.valor } : {}),
63	  };
64	  return ok({ ...estado, contas: [...estado.contas, conta] });
65	}
