138	export interface SaldoTotal {
139	  /** Soma das contas ativas que não são cartão. */
140	  contas: Centavos;
141	  /** Saldo dos cartões ativos; negativo quando há fatura em aberto. */
142	  cartoes: Centavos;
143	  /** Contas mais cartões (a fatura em aberto é subtraída). */
144	  total: Centavos;
145	}
146	
147	export function saldoTotal(estado: DadosDeSaldo): SaldoTotal {
148	  const saldos = saldosPorConta(estado);
149	  let contas = 0;
150	  let cartoes = 0;
151	  for (const c of estado.contas) {
152	    if (c.arquivada) continue;
153	    const saldo = saldos.get(c.id) ?? 0;
154	    if (c.tipo === 'cartao') cartoes += saldo;
155	    else contas += saldo;
156	  }
157	  return { contas, cartoes, total: contas + cartoes };
158	}
