import { useEffect, useId, useRef, useState } from 'react';
import { Botao, CampoTexto } from './ui';

interface Props {
  titulo: string;
  mensagem: string;
  rotuloConfirmar: string;
  perigo?: boolean;
  /** Se informado, o usuário precisa digitar exatamente este texto para confirmar. */
  textoDigitado?: string;
  onConfirmar: () => void;
  onCancelar: () => void;
}

/** Diálogo modal de confirmação. Renderize-o apenas quando estiver aberto. */
export function ConfirmDialog({ titulo, mensagem, rotuloConfirmar, perigo, textoDigitado, onConfirmar, onCancelar }: Props) {
  const idTitulo = useId();
  const [digitado, setDigitado] = useState('');
  const raiz = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const alvo = raiz.current?.querySelector<HTMLElement>('input, button');
    alvo?.focus();
  }, []);

  useEffect(() => {
    const aoTeclar = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onCancelar();
    };
    document.addEventListener('keydown', aoTeclar);
    return () => document.removeEventListener('keydown', aoTeclar);
  }, [onCancelar]);

  const liberado = textoDigitado === undefined || digitado === textoDigitado;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/50 p-4">
      <div ref={raiz} role="dialog" aria-modal="true" aria-labelledby={idTitulo} className="w-full max-w-md rounded-lg bg-white p-5 shadow-xl">
        <h2 id={idTitulo} className="text-lg font-semibold text-slate-900">
          {titulo}
        </h2>
        <p className="mt-2 text-sm text-slate-700">{mensagem}</p>
        {textoDigitado !== undefined ? (
          <div className="mt-3">
            <CampoTexto label={`Digite ${textoDigitado} para confirmar`} value={digitado} onChange={(e) => setDigitado(e.target.value)} autoComplete="off" />
          </div>
        ) : null}
        <div className="mt-4 flex justify-end gap-2">
          <Botao variante="secundario" onClick={onCancelar}>
            Cancelar
          </Botao>
          <Botao variante={perigo ? 'perigo' : 'primario'} disabled={!liberado} onClick={onConfirmar}>
            {rotuloConfirmar}
          </Botao>
        </div>
      </div>
    </div>
  );
}

import { useState, type FormEvent } from 'react';
import { hojeISO } from '../domain/date';
import { parseValor, valorParaCampo } from '../domain/money';
import type { DadosPagamento } from '../domain/cartoes';
import type { Conta, Mes, Resultado } from '../domain/types';
import { Alerta, Botao, CampoSelect, CampoTexto } from './ui';

interface Props {
  contaCartaoId: string;
  mesFatura: Mes;
  restante: number;
  contasOrigem: Conta[];
  onSalvar: (dados: DadosPagamento) => Resultado<void>;
}

type Erros = Partial<Record<'valor' | 'data' | 'contaOrigemId' | 'geral', string>>;

export function PagamentoFaturaForm({ contaCartaoId, mesFatura, restante, contasOrigem, onSalvar }: Props) {
  const [valor, setValor] = useState(restante > 0 ? valorParaCampo(restante) : '');
  const [data, setData] = useState(hojeISO());
  const [origem, setOrigem] = useState(contasOrigem[0]?.id ?? '');
  const [erros, setErros] = useState<Erros>({});

  if (contasOrigem.length === 0) {
    return <Alerta tipo="aviso">Para pagar a fatura é preciso ter uma conta ativa que não seja cartão.</Alerta>;
  }

  const enviar = (e: FormEvent) => {
    e.preventDefault();
    const centavos = parseValor(valor);
    if (centavos === null) return setErros({ valor: 'Informe um valor válido, como 350,00.' });
    const r = onSalvar({ contaCartaoId, mesFatura, valor: centavos, data, contaOrigemId: origem });
    if (!r.ok) return setErros(r.campo ? { [r.campo]: r.erro } : { geral: r.erro });
    setErros({});
  };

  return (
    <form onSubmit={enviar} noValidate aria-label="Pagar fatura" className="grid gap-3 sm:grid-cols-3">
      <CampoTexto label="Valor do pagamento" value={valor} onChange={(e) => setValor(e.target.value)} erro={erros.valor} inputMode="decimal" placeholder="0,00" />
      <CampoTexto label="Data do pagamento" type="date" value={data} onChange={(e) => setData(e.target.value)} erro={erros.data} />
      <CampoSelect label="Pagar com a conta" value={origem} onChange={(e) => setOrigem(e.target.value)} erro={erros.contaOrigemId}>
        {contasOrigem.map((c) => (
          <option key={c.id} value={c.id}>
            {c.nome}
          </option>
        ))}
      </CampoSelect>
      {erros.geral ? (
        <div className="sm:col-span-3">
          <Alerta>{erros.geral}</Alerta>
        </div>
      ) : null}
      <div className="sm:col-span-3">
        <Botao type="submit">Registrar pagamento</Botao>
      </div>
    </form>
  );
}
