  contaDestinoId: string;
  /** Sempre positivo, em centavos inteiros. */
  valor: Centavos;
  data: DataISO;
  descricao: string;
  criadaEm: number;
}

export type DadosTransferencia = Omit<Transferencia, 'id' | 'criadaEm'>;

